        "elements": [
          {
            "id": "home_about_label",
            "elType": "widget",
            "widgetType": "text-editor",
            "settings": {
              "editor": "<p style='color:#13A89E;font-weight:700;font-size:14px;text-transform:uppercase;letter-spacing:2px;'>About Chirox</p>",
              "align": "left"
            }
          },
          {
            "id": "home_about_title",
            "elType": "widget",
            "widgetType": "heading",
            "settings": {
              "title": "We Are Dedicated to Your Spinal Health & Overall Wellness",
              "align": "left",
              "header_size": "h2",
              "title_color": "#0B2545",
              "typography_typography": "custom",
              "typography_font_family": "Plus Jakarta Sans",
