              "typography_font_weight": "800",
              "typography_line_height": {"size": 1.3, "unit": "em"}
            }
          },
          {
            "id": "home_about_text",
            "elType": "widget",
            "widgetType": "text-editor",
            "settings": {
              "editor": "<p>Chiropractic is a form of alternative medicine that focuses on diagnosing and treating mechanical disorders of the musculoskeletal system, particularly the spine. Our clinic combines traditional chiropractic methods with modern physiotherapy techniques to provide comprehensive care.</p><p>Our team of experienced practitioners is committed to helping you achieve pain-free living through personalized treatment plans tailored to your specific needs.</p>",
              "text_color": "#555555",
              "typography_typography": "custom",
              "typography_font_size": {"size": 16, "unit": "px"},
              "typography_line_height": {"size": 1.8, "unit": "em"}
            }
          },
          {
            "id": "home_about_btn",
            "elType": "widget",
            "widgetType": "button",
            "settings": {
              "text": "Learn More About Us",
              "link": {"url": "/about", "is_external": false, "nofollow": false},
              "size": "md",
              "background_color": "#13A89E",
              "button_text_color": "#FFFFFF",
              "border_radius": {"top": "8", "right": "8", "bottom": "8", "left": "8", "unit": "px"},
              "typography_font_weight": "700"
            }
          }
        ]
      }
    ]
  },
